<?php
require_once dirname(__DIR__).'/config.php';
require_once dirname(__DIR__).'/includes/archive_ui.php';
requireCapability('archive.manage');
header('Cache-Control: private, no-store, max-age=0');
$db=connectDb();$error='';$notice='';$detail=null;$list=null;
if($_SERVER['REQUEST_METHOD']==='POST') {
    requireWorkflowCsrf();
    try {$result=archiveRestore($db,$_POST);setFlash('success','Account restored with the approved relationship/role and a fresh password. Historical transactions, revoked passes and old sessions were preserved.');redirect('archive.php?id='.$result['event_id']);}
    catch(InvalidArgumentException|DomainException $exception){$error=$exception->getMessage();}
    catch(Throwable $exception){error_log('Archive restoration: '.$exception->getMessage());$error='Restoration could not finish. No partial changes were saved. Refresh and review the account.';}
}
try {if((int)($_GET['id']??0)>0)$detail=archiveDetails($db,(int)$_GET['id'],$_GET);else $list=archiveList($db,$_GET);}
catch(InvalidArgumentException $exception){http_response_code(400);$error=$exception->getMessage();}
$flash=getFlash();if($flash)$notice=$flash['message'];
$escape=static fn($value):string=>htmlspecialchars((string)$value,ENT_QUOTES,'UTF-8');
$queryLink=static function(array $changes)use($escape):string{return $escape('archive.php?'.http_build_query(array_replace($_GET,$changes)));};
$labels=['messages'=>'Historical Conversations','relationships'=>'Unit / Occupancy History','vehicles'=>'Registered Vehicle History','parking'=>'Visitor Parking / Reservation History','stickers'=>'Parking Sticker History','visitors'=>'Visitor / Permit History','maintenance'=>'Maintenance Requests','bookings'=>'Amenity Bookings','billing'=>'Billing & Payments','violations'=>'Violation History','job_reports'=>'Filed Job Reports','audit'=>'Audit History','events'=>'Account / Role History'];
?>
